import logging
import threading
from time import sleep
from socket import error as SocketError


class ConnectionUpkeeper(object):
    def __init__(self, connection):
        self.conn = connection
        self.keepalive_thread = threading.Thread(target=self.ping)
        self.stop_event = threading.Event()
        self.sleep_time = 300

    def start(self):
        self.keepalive_thread.setDaemon(True)
        self.keepalive_thread.start()

    def stop(self):
        self.stop_event.set()
        try:
            self.keepalive_thread.join(1.0)
        except (ReferenceError, RuntimeError):
            logging.debug('Thread already terminated, or not yet started')

    def ping(self):
        while not self.stop_event.is_set():
            sleep(self.sleep_time)
            try:
                self.conn.write(b'\r\n')
            except (AttributeError, SocketError):
                # the connection was closed
                self.stop_event.set()

    def __del__(self):
        self.stop()
